also.text:
.libraryHeader {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
}

.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  border-bottom: 1px solid var(--corpus-border);
}
.tabs {
  display: flex;
  align-items: flex-end;
  gap: 4px;
  border-bottom: 1px solid var(--corpus-border);
}
.toolbar .tabs {
  border-bottom: none;
}
.tabs button {
  border: none;
  border-bottom: 2px solid transparent;
  border-radius: 0;
  background: none;
  color: var(--corpus-muted);
  padding: 8px 12px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.tabs button:hover {
  background: none;
  color: var(--corpus-text);
}
.tabs button[aria-current="page"] {
  color: var(--corpus-text);
  border-bottom-color: var(--corpus-accent);
}
.tabsAction {
  margin-left: auto;
  padding-bottom: 6px;
}

.filters {
  display: flex;
  gap: 8px;
  align-items: center;
  padding-bottom: 8px;
}
.filters select,
.search {
  min-height: 34px;
  border: 1px solid var(--corpus-border-strong);
  border-radius: var(--corpus-radius-sm);
  background: var(--corpus-surface);
  color: var(--corpus-text);
  padding: 4px 10px;
}
.search {
  width: 240px;
}

.group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.groupTitle {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--corpus-muted);
  margin: 12px 0 0;
}
.groupTitle span {
  font-weight: 500;
}
.threadList {
  list-style: none;
  margin: 0;
  padding: 0;
  border: 1px solid var(--corpus-border);
  border-radius: var(--corpus-radius);
  background: var(--corpus-surface);
  overflow: hidden;
}
.threadRow {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: 4px 16px;
  padding: 12px 16px;
  border-top: 1px solid var(--corpus-border);
}
.threadRow:first-child {
  border-top: none;
}
.threadRow:hover {
  background: var(--corpus-surface-2);
}
.threadLink {
  display: flex;
  flex-direction: column;
  gap: 4px;
  text-align: left;
  border: none;
  background: none;
  padding: 0;
  min-height: 0;
  font-weight: 400;
}
.threadLink:hover {
  background: none;
}
.threadHead {
  display: flex;
  align-items: center;
  gap: 10px;
}
.threadTitle {
  font-size: 15px;
  font-weight: 600;
}
.threadSummary {
  color: var(--corpus-muted);
  font-size: 14px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.threadMeta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  font-size: 12.5px;
  color: var(--corpus-faint);
}
.metaStrong {
  color: var(--corpus-text);
  font-weight: 550;
}
.framework {
  font-size: 12.5px;
  color: var(--corpus-faint);
  text-align: right;
  max-width: 280px;
  padding-top: 3px;
}
.pill {
  display: inline-block;
  flex: none;
  font-size: 11.5px;
  font-weight: 600;
  line-height: 1.7;
  padding: 0 8px;
  border-radius: 999px;
  background: var(--corpus-surface-2);
  color: var(--corpus-muted);
}
.active {
  background: var(--corpus-success-soft);
  color: var(--corpus-success);
}
.frozen {
  background: var(--corpus-warning-soft);
  color: var(--corpus-warning);
}
.completed {
  background: var(--corpus-surface-2);
  color: var(--corpus-muted);
}
.cardGrid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 12px;
}
.card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
  text-align: left;
  padding: 16px;
  min-height: 0;
  font-weight: 400;
  border: 1px solid var(--corpus-border);
  border-radius: var(--corpus-radius);
  background: var(--corpus-surface);
  box-shadow: var(--corpus-shadow);
}
.card:hover {
  border-color: var(--corpus-accent);
  background: var(--corpus-surface);
}
.card span {
  color: var(--corpus-muted);
  font-size: 14px;
}
.card code {
  font: 12px / 1.5 var(--corpus-mono);
  color: var(--corpus-faint);
}
.cardTitle {
  font-size: 17px;
}
.card .activeThread {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
  color: var(--corpus-text);
}

.header {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.timeline {
  list-style: none;
  padding: 0;
  margin: 8px 0;
}
.timeline button {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  width: 100%;
  text-align: left;
  border: none;
  border-top: 1px solid var(--corpus-border);
  border-radius: 0;
  background: none;
  padding: 10px 0;
  font-weight: 400;
}
.timeline span {
  color: var(--corpus-muted);
  font-size: 13px;
}
@media (max-width: 760px) {
  .libraryHeader {
    align-items: flex-start;
    flex-direction: column;
  }
  .threadRow {
    grid-template-columns: 1fr;
  }
  .framework {
    text-align: left;
    max-width: none;
  }
  .filters {
    width: 100%;
    flex-wrap: wrap;
  }
  .search {
    width: 100%;
  }
}

location.text:
.links {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 4px 12px;
  margin: 2px 0 0;
  font-size: 12.5px;
}

also.text:
.links a {
  font-weight: 600;
  text-decoration: none;
}
.links a:hover {
  text-decoration: underline;
