.head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.head h2 {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--corpus-muted);
  margin: 0;
}

.head h2 a {
  color: inherit;
  text-decoration: none;
}
.head h2 a:hover {
  color: var(--corpus-accent);
}
.checks {
  list-style: none;
  margin: 2px 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.checks li {
  display: flex;
  flex-direction: column;
}
.checkRow {
  text-decoration: none;
  display: grid;
  grid-template-columns: 16px minmax(0, 1fr) auto;
  align-items: baseline;
  gap: 6px;
  width: 100%;
  padding: 3px 4px;
  margin: 0 -4px;
  border-radius: var(--corpus-radius-sm);
  color: inherit;
}
.checkRow:hover {
  background: var(--corpus-surface-2);
}
.checkRow:focus-visible,
.missionName:focus-visible {
  outline: 2px solid var(--corpus-accent);
  outline-offset: 1px;
}
.status {
  font-size: 11.5px;
  color: var(--corpus-faint);
}
.checkRow .status {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 22ch;
}
.mark {
  text-align: center;
  font-size: 12px;
}
.name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.satisfied .mark,
.satisfied .status {
  color: var(--corpus-success);
}
.failed .mark,
.failed .status {
  color: var(--corpus-danger);
}
.actionable .mark,
.actionable .status,
.running .mark,
.running .status {
  color: var(--corpus-accent);
}
.running .mark {
  animation: corpus-monitor-running 1.2s linear infinite;
}
.running .status {
  display: inline-flex;
  gap: 6px;
}
@keyframes corpus-monitor-running {
  to {
    transform: rotate(360deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  .running .mark {
    animation: none;
  }
}
.blocked {
  color: var(--corpus-muted);
}

.missionList {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.mission {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  border: 1px solid var(--corpus-border);
  border-radius: var(--corpus-radius-sm);
  padding: 6px 10px 8px;
  background: var(--corpus-surface);
}
.missionHead {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}
.missionName {
  flex: 1;
  min-width: 0;
  color: var(--corpus-text);
  font: 600 12.5px var(--corpus-mono);
  text-decoration: none;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.missionName:hover {
  color: var(--corpus-accent);
  text-decoration: underline;
}
.missionStep {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 6px;
  min-width: 0;
  font-size: 12px;
  color: var(--corpus-muted);
}
.nextName {
  min-width: 0;
  overflow-wrap: anywhere;
}
.missionTime {
  margin: 0;
  color: var(--corpus-faint);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
  overflow-wrap: normal;
}
.nestedList {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 6px 0 0;
  padding: 0 0 0 10px;
  border-left: 2px solid var(--corpus-border);
  list-style: none;
}

.checkItem .mark {
  position: relative;
  z-index: 1;
  background: var(--corpus-surface);
  border-radius: 999px;
  line-height: 16px;
}

.satisfied .mark {
  color: var(--corpus-success);
}
.failed .mark {
  color: var(--corpus-danger);
}
.actionable .mark,
.running .mark {
  color: var(--corpus-accent);
}
.running .mark {
  animation: corpus-running-turn 1.2s linear infinite;
}

@media (prefers-reduced-motion: reduce) {
  .running .mark {
    animation: none;
  }
}

