related.text:
export const threadState = (thread: Pick<Thread, "state">, atWork = false): PillState => {
  switch (thread.state) {
    case "ACTIVE":
      return atWork ? { label: "In progress", role: "warning" } : { label: "Open", role: "accent" };
    case "FROZEN":
      return { label: "Paused", role: "waiting" };
    case "COMPLETED":
      return { label: "Completed", role: "success" };
    default:
      throw new Error(`Unknown thread state: ${String(thread.state)}`);
  }
};
